-- Batch Release IQ – database schema (PostgreSQL)
-- Run this inside the empty database you created, then start the API with Database:SeedSampleData
-- true (demo data) or false (empty system). Generated from the EF Core model; do not edit by hand.
CREATE TABLE "AuditEntries" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Timestamp" timestamp with time zone NOT NULL,
    "UserId" integer,
    "Username" text NOT NULL,
    "Action" text NOT NULL,
    "EntityType" text NOT NULL,
    "EntityId" text NOT NULL,
    "BatchId" integer,
    "FieldName" text,
    "OldValue" text,
    "NewValue" text,
    "Reason" text,
    CONSTRAINT "PK_AuditEntries" PRIMARY KEY ("Id")
);


CREATE TABLE "Customers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "Country" text NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Customers" PRIMARY KEY ("Id")
);


CREATE TABLE "Departments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    CONSTRAINT "PK_Departments" PRIMARY KEY ("Id")
);


CREATE TABLE "ExternalParties" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "PartyType" character varying(40) NOT NULL,
    "City" text NOT NULL,
    "Country" text NOT NULL,
    "IsApproved" boolean NOT NULL,
    "QualityAgreementValidUntil" date,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_ExternalParties" PRIMARY KEY ("Id")
);


CREATE TABLE "Markets" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "RegulatoryAuthority" text NOT NULL,
    "MinShelfLifePctAtDispatch" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Markets" PRIMARY KEY ("Id")
);


CREATE TABLE "PrioritySettings" (
    "Id" integer NOT NULL,
    "ReadinessBandSize" integer NOT NULL,
    "BlockedItemPenalty" numeric(8,2) NOT NULL,
    "OpenEventPenalty" numeric(8,2) NOT NULL,
    "CriticalEventPenalty" numeric(8,2) NOT NULL,
    "MaxPenalty" numeric(8,2) NOT NULL,
    "MinStageWeight" numeric(8,2) NOT NULL,
    "MaxStageWeight" numeric(8,2) NOT NULL,
    "StuckDays" integer NOT NULL,
    "ExpiryWarningDays" integer NOT NULL,
    "AtRiskBufferDays" integer NOT NULL,
    "DefaultItemDurationDays" numeric(8,2) NOT NULL,
    "EnforceSegregationOfDuties" boolean NOT NULL,
    CONSTRAINT "PK_PrioritySettings" PRIMARY KEY ("Id")
);


CREATE TABLE "Products" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "Strength" text NOT NULL,
    "StrengthUnit" text NOT NULL,
    "DosageForm" text NOT NULL,
    "ProductType" text NOT NULL,
    "PackSize" text NOT NULL,
    "ShelfLifeMonths" integer NOT NULL,
    "BatchPrefix" text NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Products" PRIMARY KEY ("Id")
);


CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "IsSystem" boolean NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);


CREATE TABLE "Signatures" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Username" text NOT NULL,
    "FullName" text NOT NULL,
    "Meaning" text NOT NULL,
    "SignedAt" timestamp with time zone NOT NULL,
    "EntityType" text NOT NULL,
    "EntityId" text NOT NULL,
    "BatchId" integer,
    "RecordHash" text NOT NULL,
    CONSTRAINT "PK_Signatures" PRIMARY KEY ("Id")
);


CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" text NOT NULL,
    "FullName" text NOT NULL,
    "Email" text NOT NULL,
    "DepartmentId" integer,
    "PasswordHash" text NOT NULL,
    "IsActive" boolean NOT NULL,
    "FailedLoginCount" integer NOT NULL,
    "LockedUntil" timestamp with time zone,
    "LastLoginAt" timestamp with time zone,
    "PasswordChangedAt" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id")
);


CREATE TABLE "Sites" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "City" text NOT NULL,
    "Country" text NOT NULL,
    "SiteType" character varying(40) NOT NULL,
    "ExternalPartyId" integer,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Sites" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Sites_ExternalParties_ExternalPartyId" FOREIGN KEY ("ExternalPartyId") REFERENCES "ExternalParties" ("Id")
);


CREATE TABLE "Templates" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Description" text NOT NULL,
    "Version" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "Priority" integer NOT NULL,
    "ProductId" integer,
    "DosageForm" text,
    "MarketId" integer,
    "CustomerId" integer,
    "BatchType" character varying(40),
    "SiteType" character varying(40),
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Templates" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Templates_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id"),
    CONSTRAINT "FK_Templates_Markets_MarketId" FOREIGN KEY ("MarketId") REFERENCES "Markets" ("Id"),
    CONSTRAINT "FK_Templates_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id")
);


CREATE TABLE "RolePermissions" (
    "RoleId" integer NOT NULL,
    "PermissionCode" text NOT NULL,
    CONSTRAINT "PK_RolePermissions" PRIMARY KEY ("RoleId", "PermissionCode"),
    CONSTRAINT "FK_RolePermissions_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);


CREATE TABLE "UserRoles" (
    "UserId" integer NOT NULL,
    "RoleId" integer NOT NULL,
    CONSTRAINT "PK_UserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_UserRoles_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Batches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BatchNo" text NOT NULL,
    "ProductId" integer NOT NULL,
    "SiteId" integer NOT NULL,
    "CustomerId" integer,
    "BatchType" character varying(40) NOT NULL,
    "ParentBatchId" integer,
    "LotType" text NOT NULL,
    "BatchSize" numeric(18,3) NOT NULL,
    "BatchSizeUnit" text NOT NULL,
    "ManufacturingBlock" text NOT NULL,
    "ProcessOrderDate" date,
    "ManufacturingDate" date NOT NULL,
    "BatchCompletionDate" date,
    "TargetReleaseDate" date NOT NULL,
    "ShelfLifeMonths" integer NOT NULL,
    "ExpiryDate" date NOT NULL,
    "ExpiryOverrideReason" text,
    "Disposition" character varying(40) NOT NULL,
    "DispositionReason" text,
    "TemplateId" integer,
    "TemplateVersion" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedById" integer NOT NULL,
    "ReadinessPct" numeric(5,1) NOT NULL,
    "IsReadyForRelease" boolean NOT NULL,
    "CurrentStage" text NOT NULL,
    "LastProgressAt" timestamp with time zone,
    "DispatchByDate" date NOT NULL,
    "Deadline" date NOT NULL,
    "DeadlineType" character varying(40) NOT NULL,
    "ReleasedAt" timestamp with time zone,
    CONSTRAINT "PK_Batches" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Batches_Batches_ParentBatchId" FOREIGN KEY ("ParentBatchId") REFERENCES "Batches" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Batches_Customers_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "Customers" ("Id"),
    CONSTRAINT "FK_Batches_Products_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Products" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Batches_Sites_SiteId" FOREIGN KEY ("SiteId") REFERENCES "Sites" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Batches_Templates_TemplateId" FOREIGN KEY ("TemplateId") REFERENCES "Templates" ("Id"),
    CONSTRAINT "FK_Batches_Users_CreatedById" FOREIGN KEY ("CreatedById") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "TemplateItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TemplateId" integer NOT NULL,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "Stage" text NOT NULL,
    "DepartmentId" integer NOT NULL,
    "ItemType" character varying(40) NOT NULL,
    "IsMandatory" boolean NOT NULL,
    "Weight" numeric(6,2),
    "Sequence" integer NOT NULL,
    "DueOffsetDays" integer NOT NULL,
    "IsFinalRelease" boolean NOT NULL,
    "IsPerMarket" boolean NOT NULL,
    "DefaultSource" character varying(40) NOT NULL,
    "DependsOn" text NOT NULL,
    CONSTRAINT "PK_TemplateItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TemplateItems_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_TemplateItems_Templates_TemplateId" FOREIGN KEY ("TemplateId") REFERENCES "Templates" ("Id") ON DELETE CASCADE
);


CREATE TABLE "BatchMarkets" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BatchId" integer NOT NULL,
    "MarketId" integer NOT NULL,
    "RegulatoryStatus" character varying(40) NOT NULL,
    "ApprovalReference" text,
    "ApprovedAt" timestamp with time zone,
    "Source" character varying(40) NOT NULL,
    "LastSyncedAt" timestamp with time zone,
    CONSTRAINT "PK_BatchMarkets" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BatchMarkets_Batches_BatchId" FOREIGN KEY ("BatchId") REFERENCES "Batches" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_BatchMarkets_Markets_MarketId" FOREIGN KEY ("MarketId") REFERENCES "Markets" ("Id") ON DELETE CASCADE
);


CREATE TABLE "ChangeRequests" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BatchId" integer NOT NULL,
    "ChangeType" character varying(40) NOT NULL,
    "ChecklistItemId" integer,
    "ProposedName" text,
    "ProposedStage" text,
    "ProposedDepartmentId" integer,
    "ProposedItemType" character varying(40),
    "ProposedIsMandatory" boolean,
    "ProposedWeight" numeric(6,2),
    "ProposedSequence" integer,
    "ProposedDueDate" date,
    "Reason" text NOT NULL,
    "Status" character varying(40) NOT NULL,
    "RequestedById" integer NOT NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "DecidedById" integer,
    "DecidedAt" timestamp with time zone,
    "DecisionComment" text,
    "SignatureId" integer,
    CONSTRAINT "PK_ChangeRequests" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ChangeRequests_Batches_BatchId" FOREIGN KEY ("BatchId") REFERENCES "Batches" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ChangeRequests_Signatures_SignatureId" FOREIGN KEY ("SignatureId") REFERENCES "Signatures" ("Id"),
    CONSTRAINT "FK_ChangeRequests_Users_DecidedById" FOREIGN KEY ("DecidedById") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ChangeRequests_Users_RequestedById" FOREIGN KEY ("RequestedById") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "ChecklistItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BatchId" integer NOT NULL,
    "TemplateItemId" integer,
    "Code" text NOT NULL,
    "Name" text NOT NULL,
    "Stage" text NOT NULL,
    "DepartmentId" integer NOT NULL,
    "ItemType" character varying(40) NOT NULL,
    "IsMandatory" boolean NOT NULL,
    "Weight" numeric(6,2) NOT NULL,
    "Sequence" integer NOT NULL,
    "IsFinalRelease" boolean NOT NULL,
    "MarketId" integer,
    "ExternalMovementId" integer,
    "Status" character varying(40) NOT NULL,
    "DueDate" date,
    "StartedAt" timestamp with time zone,
    "CompletedAt" timestamp with time zone,
    "CompletedById" integer,
    "Comments" text,
    "NotApplicableJustification" text,
    "BlockedReason" text,
    "EvidenceReference" text,
    "Source" character varying(40) NOT NULL,
    "SourceReference" text,
    "LastSyncedAt" timestamp with time zone,
    "IsRemoved" boolean NOT NULL,
    CONSTRAINT "PK_ChecklistItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ChecklistItems_Batches_BatchId" FOREIGN KEY ("BatchId") REFERENCES "Batches" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ChecklistItems_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ChecklistItems_Markets_MarketId" FOREIGN KEY ("MarketId") REFERENCES "Markets" ("Id"),
    CONSTRAINT "FK_ChecklistItems_Users_CompletedById" FOREIGN KEY ("CompletedById") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);


CREATE TABLE "Dispatches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
